// This file is generated by AI.

// 文档代码块 (hover / 补全项的 ```webgal) 的高亮桥接: 把**后端的高亮结果**转译成 Monaco
// 的 tokenizer。
//
// 为什么要转译: Monaco 渲染代码块 (hover: markdownHoverParticipant.js; 补全:
// suggestWidgetDetails.js) 时走 `MarkdownRenderer.codeBlockRenderer` ->
// `textToHtmlTokenizer.js` 的 `tokenizeToString(...)`, 内部**同步**调用
// `TokenizationRegistry.getOrCreate(languageId)`。也就是说 Monaco 只会拿"语言注册的
// tokenizer"给代码块着色, 它不会自己把 LSP 的 semantic tokens 用到代码块上。而 WebGAL 的
// 高亮规则在仓库里只有后端一份 (语言服务), 前端不重复实现 —— 这里只做转译:
//
//   1. 从 markdown 里找出 ```webgal 代码块, 交给后端高亮 (Ink: `highlight_scene_all` 命令;
//      Playground: wasm 的 `Scene::highlight`);
//   2. 把后端返回的 LSP `SemanticTokens.data` 按行拆开缓存;
//   3. 注册一个只读缓存的 `TokensProvider`, 供 Monaco 渲染代码块时同步取用。
//
// token 名取自后端图例 (下标 -> 名字), 颜色仍由当前主题决定, 所以代码块的配色与编辑器里的
// 语义高亮完全一致。

/** Monaco `IToken`: token 名就是主题作用域 (颜色由主题决定)。 */
export interface DocToken {
  startIndex: number;
  scopes: string;
}

/** Monaco 要求 state 提供 `clone` / `equals` (见 standaloneLanguages.js 的 adaptTokenize)。 */
export interface DocTokenizerState {
  clone(): DocTokenizerState;
  equals(other: DocTokenizerState): boolean;
}

export interface DocTokenizationResult {
  tokens: DocToken[];
  endState: DocTokenizerState;
}

/** Monaco `TokensProvider` 的最小接口 (两处 monaco 版本不同, 这里不依赖具体版本)。 */
export interface DocTokensProvider {
  getInitialState(): DocTokenizerState;
  tokenize(line: string, state: DocTokenizerState): DocTokenizationResult;
}

export interface DocTokensHost {
  languages: {
    setTokensProvider(languageId: string, provider: DocTokensProvider): unknown;
  };
}

/** 后端高亮: 输入任意一段场景文本, 返回扁平化的 LSP `SemanticTokens.data`。 */
export type HighlightText = (text: string) => ArrayLike<number> | Promise<ArrayLike<number>>;

/** 抽出 markdown 里所有 ```webgal / ~~~webgal 代码块的文本。 */
export function extractWebgalCodeBlocks(markdown: string): string[] {
  const blocks: string[] = [];
  let fence: { char: string; length: number } | null = null;
  let content: string[] = [];

  for (const line of markdown.split('\n')) {
    if (fence === null) {
      // 围栏起始行: ``` 或 ~~~ 后第一个词是 webgal (document.json 里写作 "``` webgal")
      const open = /^\s*(`{3,}|~{3,})[ \t]*([^\s`]*)/.exec(line);
      if (open && open[2].toLowerCase() === 'webgal') {
        fence = { char: open[1][0], length: open[1].length };
        content = [];
      }
      continue;
    }

    // 围栏结束行: 同种围栏字符且不短于起始围栏
    const close = /^\s*(`{3,}|~{3,})\s*$/.exec(line);
    if (close && close[1][0] === fence.char && close[1].length >= fence.length) {
      blocks.push(content.join('\n'));
      fence = null;
      content = [];
      continue;
    }

    content.push(line);
  }

  return blocks;
}

/**
 * 解码后端返回的扁平化 LSP `SemanticTokens.data`。
 *
 * 每 5 个整数为一个 token: `deltaLine` / `deltaStart` / `length` / `tokenType` / `modifiers`,
 * 行起点与 `deltaLine` 为文档绝对行号 (后端 `highlight` / `highlight_range` 的约定),
 * 列偏移也已由后端转成 UTF-16 (匹配 Monaco)。
 */
export function decodeSemanticTokens(data: ArrayLike<number>, tokenTypes: readonly string[]): Map<number, DocToken[]> {
  const byLine = new Map<number, DocToken[]>();
  let line = 0;
  let start = 0;

  for (let i = 0; i + 4 < data.length; i += 5) {
    const deltaLine = data[i];
    const deltaStart = data[i + 1];
    const length = data[i + 2];
    const tokenType = data[i + 3];

    if (deltaLine === 0) {
      start += deltaStart;
    } else {
      line += deltaLine;
      start = deltaStart;
    }

    // 后端每行末尾会补一个零长度 token, 无意义 (Monaco 也会判为非法长度并丢弃)
    if (length === 0) continue;

    const tokens = byLine.get(line) ?? [];
    tokens.push({ startIndex: start, scopes: tokenTypes[tokenType] ?? '' });
    byLine.set(line, tokens);
  }

  return byLine;
}

export interface CodeBlockHighlight {
  /** 注册只读缓存的 tokenizer (对应语言需已注册, 只需调用一次)。 */
  install(host: DocTokensHost, languageId: string): void;
  /** 把 markdown 里的 ```webgal 代码块交给后端高亮并缓存 (渲染它们之前调用)。 */
  prime(markdown: string, tokenTypes: readonly string[], highlight: HighlightText): Promise<void>;
}

/** 创建代码块高亮桥接 (内部缓存与解析器一一对应)。 */
export function createCodeBlockHighlight(): CodeBlockHighlight {
  // 去掉首尾空白的行文本 -> 该行的 token (列号相对去掉首尾空白后的行)
  const tokensByLine = new Map<string, DocToken[]>();
  // 已送去后端高亮的代码块 (同一段文档可能被多个补全项 / 多次 hover 复用)
  const primed = new Set<string>();

  const cacheBlock = (block: string, byLine: Map<number, DocToken[]>) => {
    const lines = block.split('\n');
    for (const [index, tokens] of byLine) {
      const line = lines[index];
      if (line === undefined) continue;

      const trimmed = line.trim();
      if (!trimmed) continue;

      // 按"去掉首尾空白的行"缓存: 围栏缩进 (marked 会按围栏缩进去掉前导空白) 不影响命中
      const shift = line.length - line.trimStart().length;
      tokensByLine.set(
        trimmed,
        tokens.map((token) => ({ startIndex: token.startIndex - shift, scopes: token.scopes }))
      );
    }
  };

  const tokensForLine = (line: string): DocToken[] => {
    const plain: DocToken = { startIndex: 0, scopes: '' };
    const trimmed = line.trim();
    const cached = trimmed ? tokensByLine.get(trimmed) : undefined;
    if (!cached) return [plain];

    const shift = line.length - line.trimStart().length;
    const tokens = cached.map((token) => ({ startIndex: token.startIndex + shift, scopes: token.scopes }));
    // Monaco 会强制第一个 token 从 0 开始 (standaloneLanguages.js `_toBinaryTokens`),
    // 这里显式补一个不着色的首 token, 免得行首空白被着成第一个 token 的颜色
    if (tokens.length === 0) return [plain];

    // Monaco 会强制第一个 token 从 0 开始 (standaloneLanguages.js `_toBinaryTokens`),
    // 这里显式补一个不着色的首 token, 免得行首空白被着成第一个 token 的颜色
    return tokens[0].startIndex === 0 ? tokens : [plain, ...tokens];
  };

  return {
    install(host, languageId) {
      // 无状态 tokenizer: 所有行共用同一个 state
      const state: DocTokenizerState = { clone: () => state, equals: (other) => other === state };
      host.languages.setTokensProvider(languageId, {
        getInitialState: () => state,
        tokenize: (line) => ({ tokens: tokensForLine(line), endState: state }),
      });
    },

    async prime(markdown, tokenTypes, highlight) {
      const blocks = extractWebgalCodeBlocks(markdown).filter((block) => block.trim() !== '' && !primed.has(block));

      await Promise.all(
        blocks.map(async (block) => {
          // 先登记再 await: 并发调用 (如整批补全项) 时同一代码块只高亮一次
          primed.add(block);
          try {
            cacheBlock(block, decodeSemanticTokens(await highlight(block), tokenTypes));
          } catch {
            // 后端高亮失败时该代码块保持无高亮, 不影响 hover / 补全本身; 允许下次重试
            primed.delete(block);
          }
        })
      );
    },
  };
}
